  ["pr", "gh pr view 2131 --repo entireio/cli --json number,title,body,state,url,isDraft,mergeStateStatus,reviewDecision,files,commits,comments,reviews", 30000],
  ["diff", "gh pr diff 2131 --repo entireio/cli", 30000]
];
const out = await Promise.all(cmds.map(async ([name,cmd,yield_time_ms]) => {
  const r = await tools.exec_command({cmd,workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/improve-process-sessions-condensation",yield_time_ms,max_output_tokens:30000});
  return {name,...r};
}));
for (const x of out) {
  text(`--- ${x.name} (exit ${x.exit_code}) ---\n${x.output}`);
}

const cmds = [
  ["issue", "gh issue view 2091 --repo entireio/cli --json number,title,body,state,url,comments"],
  ["pr", "gh pr view 2131 --repo entireio/cli --json number,title,body,state,url,isDraft,mergeStateStatus,reviewDecision,files,commits,comments,reviews"],
  ["diff", "gh pr diff 2131 --repo entireio/cli"]
];
const out = [];
for (const [name,cmd] of cmds) {
  const r = await tools.exec_command({
    cmd,
    workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/improve-process-sessions-condensation",
    yield_time_ms:30000,
    max_output_tokens:30000,
    sandbox_permissions:"require_escalated",
    justification:"May I use read-only GitHub access to inspect issue #2091 and PR #2131 so I can draft an accurate maintainer reply?",
    prefix_rule:["gh"]
  });
  out.push({name,...r});
  if (r.exit_code !== 0) break;
}
for (const x of out) text(`--- ${x.name} (exit ${x.exit_code}) ---\n${x.output}`);

