+	lockHeld := make(chan struct{})
+	releaseLock := make(chan struct{})
+	holderDone := make(chan error, 1)
+	go func() {
+		holderDone <- strategy.MutateSessionState(context.Background(), sessionID, func(*strategy.SessionState) error {
+			close(lockHeld)
