+func writeAfter(t *testing.T, delay time.Duration, write func() error) <-chan error {
+	t.Helper()
+
+	done := make(chan error, 1)
+	go func() {
+		timer := time.NewTimer(delay)
+		defer timer.Stop()
+		<-timer.C
+		done <- write()
+	}()
+	return done
+}
