+func replaceSourceAfterOwnedCopy(ownedPath, sourcePath string, expected []byte, result chan<- mutationObservation) {
+	deadline := time.Now().Add(10 * time.Second)
+	for time.Now().Before(deadline) {
+		owned, err := os.ReadFile(ownedPath)
+		if err == nil && string(owned) == string(expected) {
+			mutated := strings.Repeat(`{"type":"assistant","message":{"content":"mutated live source"}}`+"\n", 20)
+			writeErr := os.WriteFile(sourcePath, []byte(mutated), 0o600)
+			result <- mutationObservation{at: time.Now(), err: writeErr}
+			return
+		}
+		time.Sleep(time.Millisecond)
+	}
+	result <- mutationObservation{err: fmt.Errorf("owned transcript %s did not appear", ownedPath)}
+}"},{"sha":"dd948ce449a115322423f44793ffa8d72a17673d","filename":"cmd/entire/cli/integration_test/deferred_finalization_test.go","status":"modified","additions":29,"deletions":7,"changes":36,"blob_url":"https://github.com/entireio/cli/blob/d6bcbf51b9538a338e599e58675e0582a5ee36b1/cmd%2Fentire%2Fcli%2Fintegration_test%2Fdeferred_finalization_test.go","raw_url":"https://github.com/entireio/cli/raw/d6bcbf51b9538a338e599e58675e0582a5ee36b1/cmd%2Fentire%2Fcli%2Fintegration_test%2Fdeferred_finalization_test.go","contents_url":"https://api.github.com/repos/entireio/cli/contents/cmd%2Fentire%2Fcli%2Fintegration_test%2Fdeferred_finalization_test.go?ref=d6bcbf51b9538a338e599e58675e0582a5ee36b1","patch":"@@ -6,6 +6,7 @@ import (
