+	require.NoError(t, os.WriteFile(transcriptPath, first, 0o600))
+
+	ag := &mockRepeatableCapturerAgent{
+		mockCapturerAgent: &mockCapturerAgent{
+			mockLifecycleAgent: *newMockAgent(),
