+	z := WriteOptions(batchTestSession(checkpointID, "session-z"))
+	z.Strategy = ""
+	z.Branch = ""
+	z.CommitSHA = ""
+	z.FilesTouched = []string{"c.go", "a.go"}
+	z.TokenUsage = &types.TokenUsage{InputTokens: 3}
+	z.CheckpointsCount = 3
