-		return fmt.Errorf("failed to update persistent ref %s after %d CAS retries: %w", refName, shadowRefMaxRetries, ErrShadowRefBusy)
-	})
-}"},{"sha":"47063080fa3da53d001ca3a7d407915ff0fd86f3","filename":"cmd/entire/cli/checkpoint/persistent_ref_update_test.go","status":"removed","additions":0,"deletions":150,"changes":150,"blob_url":"https://github.com/entireio/cli/blob/c7a96436dc255d55b885dd80bed2f6809d90a748/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_update_test.go","raw_url":"https://github.com/entireio/cli/raw/c7a96436dc255d55b885dd80bed2f6809d90a748/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_update_test.go","contents_url":"https://api.github.com/repos/entireio/cli/contents/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_update_test.go?ref=c7a96436dc255d55b885dd80bed2f6809d90a748","patch":"@@ -1,150 +0,0 @@
