+func concurrentSession(checkpointID id.CheckpointID, sessionID string) Session {
+	return Session{
+		CheckpointID: checkpointID,
+		SessionID:    sessionID,
+		Strategy:     "manual-commit",
+		Transcript:   redact.AlreadyRedacted([]byte(sessionID + " transcript\n")),
+		Prompts:      []string{"do the work"},
+		FilesTouched: []string{sessionID + ".go"},
+		AuthorName:   "Test Author",
+		AuthorEmail:  "test@example.com",
+	}
+}
+
+func synchronizedFirstCAS(t *testing.T) (context.Context, context.Context, func()) {
+	t.Helper()
+	ready := make(chan struct{}, 2)
+	proceed := make(chan struct{})
+	makeContext := func() context.Context {
+		var once sync.Once
+		return withBeforeRefCAS(t.Context(), func() {
+			once.Do(func() {
+				ready <- struct{}{}
+				<-proceed
+			})
+		})
+	}
+	release := func() {
+		t.Helper()
+		<-ready
+		<-ready
+		close(proceed)
+	}
+	return makeContext(), makeContext(), release
+}"},{"sha":"e257e7437257c60e8d806a8c8ff6cbc51de7079f","filename":"cmd/entire/cli/checkpoint/persistent_ref_inventory_test.go","status":"added","additions":53,"deletions":0,"changes":53,"blob_url":"https://github.com/entireio/cli/blob/56e583e0e2f34abd5ee17319e745d509a1245bc3/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_inventory_test.go","raw_url":"https://github.com/entireio/cli/raw/56e583e0e2f34abd5ee17319e745d509a1245bc3/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_inventory_test.go","contents_url":"https://api.github.com/repos/entireio/cli/contents/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_inventory_test.go?ref=56e583e0e2f34abd5ee17319e745d509a1245bc3","patch":"@@ -0,0 +1,53 @@
+package checkpoint
