+func TestPersistentRefWritersUseNativeCASTransactions(t *testing.T) {
+	t.Parallel()
+	_, thisFile, _, ok := runtime.Caller(0)
+	if !ok {
+		t.Fatal("resolve test source path")
+	}
+	repoRoot := filepath.Clean(filepath.Join(filepath.Dir(thisFile), "..", "..", "..", ".."))
+	dirs := []string{
+		filepath.Join(repoRoot, "cmd", "entire", "cli", "checkpoint"),
+		filepath.Join(repoRoot, "cmd", "entire", "cli", "strategy"),
+	}
+	for _, dir := range dirs {
+		err := filepath.WalkDir(dir, func(path string, entry os.DirEntry, walkErr error) error {
+			if walkErr != nil {
+				return walkErr
+			}
+			if entry.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
+				return nil
+			}
+			content, err := os.ReadFile(path)
+			if err != nil {
+				return err
+			}
+			for _, forbidden := range [][]byte{
+				[]byte(".Storer.SetReference("),
+				[]byte(".Storer.CheckAndSetReference("),
+			} {
+				if bytes.Contains(content, forbidden) {
+					rel, relErr := filepath.Rel(repoRoot, path)
+					if relErr != nil {
+						rel = path
+					}
+					t.Errorf("%s bypasses the native ref CAS boundary with %s", rel, forbidden)
+				}
+			}
+			return nil
+		})
+		if err != nil {
+			t.Fatalf("scan production ref writers in %s: %v", dir, err)
+		}
+	}
+}"},{"sha":"f2b814ca841b1f6ee20849181e7bfe3f2384e0af","filename":"cmd/entire/cli/checkpoint/persistent_ref_update.go","status":"removed","additions":0,"deletions":123,"changes":123,"blob_url":"https://github.com/entireio/cli/blob/c7a96436dc255d55b885dd80bed2f6809d90a748/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_update.go","raw_url":"https://github.com/entireio/cli/raw/c7a96436dc255d55b885dd80bed2f6809d90a748/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_update.go","contents_url":"https://api.github.com/repos/entireio/cli/contents/cmd%2Fentire%2Fcli%2Fcheckpoint%2Fpersistent_ref_update.go?ref=c7a96436dc255d55b885dd80bed2f6809d90a748","patch":"@@ -1,123 +0,0 @@
