//go:build hookperf

package strategy

import (
	"bufio"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"

	"github.com/go-git/go-git/v6/plumbing"
)

func assertHookPerfFixture(t *testing.T, dir string, fixture hookPerfFixture, totalSessions int) {
	t.Helper()
	ctx := t.Context()
	stateDir := filepath.Join(dir, ".git", session.SessionStateDirName)
	states, err := session.NewStateStoreWithDir(stateDir).List(ctx)
	if err != nil {
		t.Fatalf("list seeded states: %v", err)
	}
	if len(states) != totalSessions {
		t.Fatalf("seeded state count = %d, want %d", len(states), totalSessions)
	}

	packedRefs, err := os.ReadFile(filepath.Join(dir, ".git", "packed-refs"))
	if err != nil {
		t.Fatalf("read packed refs: %v", err)
	}
	repo, err := gitrepo.OpenPath(dir)
	if err != nil {
		t.Fatalf("open repo for fixture validation: %v", err)
	}
	defer repo.Close()

	seenBases := make(map[string]struct{}, len(fixture.endedWithShadow))
	seenRefs := make(map[plumbing.ReferenceName]struct{}, len(fixture.endedWithShadow))
	for _, seeded := range fixture.endedWithShadow {
		if _, exists := seenBases[seeded.baseCommit]; exists {
			t.Fatalf("ENDED fixture reuses base commit %s", seeded.baseCommit)
		}
		seenBases[seeded.baseCommit] = struct{}{}
		if _, exists := seenRefs[seeded.shadowRef]; exists {
			t.Fatalf("ENDED fixture reuses shadow ref %s", seeded.shadowRef)
		}
		seenRefs[seeded.shadowRef] = struct{}{}
		if !strings.Contains(string(packedRefs), " "+seeded.shadowRef.String()+"\n") {
			t.Fatalf("shadow ref %s was not packed", seeded.shadowRef)
		}
		loosePath := filepath.Join(dir, ".git", filepath.FromSlash(seeded.shadowRef.String()))
		if _, statErr := os.Stat(loosePath); !os.IsNotExist(statErr) {
			t.Fatalf("shadow ref %s still exists as a loose ref", seeded.shadowRef)
		}

		ref, err := repo.Reference(seeded.shadowRef, true)
		if err != nil {
			t.Fatalf("resolve shadow ref %s: %v", seeded.shadowRef, err)
		}
		commit, err := repo.CommitObject(ref.Hash())
		if err != nil {
			t.Fatalf("resolve shadow commit for %s: %v", seeded.sessionID, err)
		}
		tree, err := commit.Tree()
		if err != nil {
			t.Fatalf("resolve shadow tree for %s: %v", seeded.sessionID, err)
		}
		if _, err := tree.File("perf_control.txt"); err != nil {
			t.Fatalf("shadow tree for %s lacks committed overlap file: %v", seeded.sessionID, err)
		}
		transcriptPath := filepath.ToSlash(filepath.Join(paths.SessionMetadataDirFromSessionID(seeded.sessionID), paths.TranscriptFileName))
		transcriptFile, err := tree.File(transcriptPath)
		if err != nil {
			t.Fatalf("shadow tree for %s lacks its transcript: %v", seeded.sessionID, err)
		}
		content, err := transcriptFile.Contents()
		if err != nil {
			t.Fatalf("read shadow transcript for %s: %v", seeded.sessionID, err)
		}
		if !strings.Contains(content, seeded.sessionID) {
			t.Fatalf("shadow transcript for %s contains another session's data", seeded.sessionID)
		}
	}
}

func assertHookPerfCondensed(t *testing.T, dir string, fixture hookPerfFixture, checkpointID id.CheckpointID) {
	t.Helper()
	ctx := t.Context()
	stateDir := filepath.Join(dir, ".git", session.SessionStateDirName)
	store := session.NewStateStoreWithDir(stateDir)
	repo, err := gitrepo.OpenPath(dir)
	if err != nil {
		t.Fatalf("open repo after PostCommit: %v", err)
	}
	defer repo.Close()

	for _, seeded := range fixture.endedWithShadow {
		state, err := store.Load(ctx, seeded.sessionID)
		if err != nil {
			t.Fatalf("load condensed state %s: %v", seeded.sessionID, err)
		}
		if state == nil {
			t.Fatalf("condensed state %s was removed", seeded.sessionID)
		}
		if state.LastCheckpointID != checkpointID {
			t.Fatalf("state %s checkpoint = %s, want %s", seeded.sessionID, state.LastCheckpointID, checkpointID)
		}
		if !state.FullyCondensed {
			t.Fatalf("state %s was not marked fully condensed", seeded.sessionID)
		}
		if _, err := repo.Reference(seeded.shadowRef, true); err == nil {
			t.Fatalf("condensed shadow ref %s was not cleaned up", seeded.shadowRef)
		}
	}
}

type hookPerfTimings struct {
	findSessions    time.Duration
	processSessions time.Duration
	condensations   int
	extract         time.Duration
	attribution     time.Duration
	redaction       time.Duration
	write           time.Duration
	condenseTotal   time.Duration
}

type hookPerfLogEntry struct {
	Message       string `json:"msg"`
	Operation     string `json:"op"`
	DurationMS    int64  `json:"duration_ms"`
	ExtractMS     int64  `json:"extract_session_data_ms"`
	AttributionMS int64  `json:"calculate_session_attribution_ms"`
	RedactionMS   int64  `json:"redact_transcript_ms"`
	WriteMS       int64  `json:"write_committed_v1_ms"`
	TotalMS       int64  `json:"total_ms"`
}

func readHookPerfTimings(t *testing.T, dir string) hookPerfTimings {
	t.Helper()
	file, err := os.Open(filepath.Join(dir, logging.LogsDir, "entire.log"))
	if err != nil {
		t.Fatalf("open performance log: %v", err)
	}
	defer file.Close()

	var timings hookPerfTimings
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 64*1024), 4*1024*1024)
	for scanner.Scan() {
		var entry hookPerfLogEntry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			t.Fatalf("parse performance log entry: %v\n%s", err, scanner.Text())
		}
		if entry.Message == "perf" {
			switch entry.Operation {
			case "find_sessions_for_worktree":
				timings.findSessions = time.Duration(entry.DurationMS) * time.Millisecond
			case "process_sessions":
				timings.processSessions = time.Duration(entry.DurationMS) * time.Millisecond
			}
		}
		if entry.Message != "condense timings" {
			continue
		}
		timings.condensations++
		timings.extract += time.Duration(entry.ExtractMS) * time.Millisecond
		timings.attribution += time.Duration(entry.AttributionMS) * time.Millisecond
		timings.redaction += time.Duration(entry.RedactionMS) * time.Millisecond
		timings.write += time.Duration(entry.WriteMS) * time.Millisecond
		timings.condenseTotal += time.Duration(entry.TotalMS) * time.Millisecond
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("scan performance log: %v", err)
	}
	if timings.processSessions == 0 {
		t.Fatal("performance log has no non-zero process_sessions measurement")
	}
	if timings.condensations == 0 {
		t.Fatal("performance log has no condensation measurements")
	}
	return timings
}

